// Implement a minimal Promise.all and a timeout wrapper to prove you understand settling and microtasks
function promiseAll(promises) {
  return new Promise((resolve, reject) => {
    const results = new Array(promises.length);
    let remaining = promises.length;
    if (remaining === 0) return resolve(results);
    promises.forEach((p, i) => {
      Promise.resolve(p).then((v) => {          // Promise.resolve adopts plain values and thenables
        results[i] = v;                          // keep INPUT order, not completion order
        if (--remaining === 0) resolve(results);
      }, reject);                                // first rejection wins (fail-fast)
    });
  });
}

const withTimeout = (p, ms) =>
  Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error(`timeout ${ms}ms`)), ms))]);

// Output order puzzle
console.log("A");
setTimeout(() => console.log("B"), 0);
Promise.resolve().then(() => console.log("C")).then(() => console.log("D"));
console.log("E");
// A E C D B

