// Typed retry + limit helpers (copy into any project)
export async function retry<T>(
  fn: (attempt: number) => Promise<T>,
  opts: { retries?: number; baseMs?: number; shouldRetry?: (e: unknown) => boolean; signal?: AbortSignal } = {},
): Promise<T> {
  const { retries = 4, baseMs = 200, shouldRetry = () => true, signal } = opts;
  for (let attempt = 0; ; attempt++) {
    try { signal?.throwIfAborted(); return await fn(attempt); }
    catch (e) {
      if (attempt >= retries || !shouldRetry(e) || signal?.aborted) throw e;
      await new Promise((r) => setTimeout(r, Math.random() * baseMs * 2 ** attempt)); // full jitter
    }
  }
}

export async function mapLimit<T, R>(items: readonly T[], limit: number, fn: (item: T, i: number) => Promise<R>): Promise<R[]> {
  const out = new Array<R>(items.length);
  let next = 0;
  const worker = async () => { for (let i = next++; i < items.length; i = next++) out[i] = await fn(items[i], i); };
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return out;
}

// In-flight de-duplication
const inflight = new Map<string, Promise<unknown>>();
export function dedupe<T>(key: string, load: () => Promise<T>): Promise<T> {
  const existing = inflight.get(key) as Promise<T> | undefined;
  if (existing) return existing;
  const p = load().finally(() => inflight.delete(key));
  inflight.set(key, p);
  return p;
}

