// Lazy pipeline with generators + a paginated async generator
function* naturals() { let n = 1; while (true) yield n++; }
function* filter(it, p) { for (const x of it) if (p(x)) yield x; }
function* map(it, f) { for (const x of it) yield f(x); }
function* take(it, n) { if (n <= 0) return; let i = 0; for (const x of it) { yield x; if (++i >= n) return; } }

const firstFiveEvenSquares = [...take(map(filter(naturals(), (n) => n % 2 === 0), (n) => n * n), 5)];
console.log(firstFiveEvenSquares);   // [4, 16, 36, 64, 100] : only as many numbers as needed were generated

// Cleanup is guaranteed with try/finally, even on early break
function* withResource() {
  console.log("open");
  try { yield 1; yield 2; yield 3; } finally { console.log("close"); }
}
for (const x of withResource()) { if (x === 2) break; }   // open, close

// Dynamic import for code splitting
async function showChart(el) {
  const { renderChart } = await import("./chart.js");     // only fetched when needed
  renderChart(el);
}

// Typed generator and iterable class
class Matrix implements Iterable<number> {
  constructor(private readonly rows: number[][]) {}
  *[Symbol.iterator](): Generator<number, void, undefined> {
    for (const r of this.rows) yield* r;      // row-major order
  }
}
console.log(Math.max(...new Matrix([[1, 9], [4, 2]])));  // 9
